        if target_x > x:
            dx = 1
        elif target_x < x:
            dx = -1
        if target_y > y:
            dy = 1
        elif target_y < y:
            dy = -1
        if dx != 0 or dy != 0:
            return [dx, dy]

    # Territory control or default: move to reduce potential loss, prefer staying or slight exploration
    # Try to move towards a quarter of the map as a simple diversification
